import test from 'node:test';
import assert from 'node:assert/strict';

import {
  MAX_OUTPUT_WIDTH,
  boundsForCanvas,
  clampView,
  eRaraTitleId,
  eRaraViewerUrl,
  fullImageUrl,
  imageRequestUrl,
  labelText,
  panView,
  parseManifest,
  parseMetadata,
  regionRequest,
  serviceId,
  viewForCanvas,
  zoomPercent,
  zoomView,
} from '../public/app/iiif.js';

/* --------------------------------------------------------------- fixtures */
...
test('regionRequest formats pixel regions and only uses full when told the bounds', () => {
  assert.equal(regionRequest({ x: 1.6, y: 2.2, w: 30, h: 40 }), '2,2,30,40');
  assert.equal(regionRequest({ x: -1, y: -1, w: 11, h: 11 }, { x: 0, y: 0, w: 10, h: 10 }), 'full');
  assert.equal(regionRequest(null), null);
});

test('fullImageUrl is a plain sizeByW request', () => {
  assert.equal(fullImageUrl('https://www.e-rara.ch/i3f/v20/1001', 304), 'https://www.e-rara.ch/i3f/v20/1001/full/304,/0/default.jpg');
});

/* ----------------------------------------------------------------- view box */

test('clampView centres a letterboxed axis and clamps the other one', () => {
  const bounds = boundsForCanvas(1000, 1000);
  assert.deepEqual(clampView({ x: -50, y: -50, w: 500, h: 500 }, bounds), { x: 0, y: 0, w: 500, h: 500 });
  assert.deepEqual(clampView({ x: 900, y: 900, w: 500, h: 500 }, bounds), { x: 500, y: 500, w: 500, h: 500 });
  assert.deepEqual(clampView({ x: 10, y: 10, w: 4000, h: 200 }, bounds), { x: 0, y: 10, w: 1000, h: 200 });
===STORE-TAIL
  const off = store.subscribe((state, changed) => seen.push([state.q, changed.join(',')]));

  store.update({ q: 'brack', nonsense: 'ignored' });
  assert.equal(store.getState().q, 'brack');
  assert.equal(store.getState().nonsense, undefined, 'unknown keys are ignored');

  store.update({ q: 'brack' }); // no change -> no notification
  store.update({ from: STATE_DEFAULTS.from - 5 }, { silent: true });

  assert.equal(seen.length, 1);
  assert.deepEqual(seen[0], ['brack', 'q']);

  off();
  store.update({ q: 'other' });
  assert.equal(seen.length, 1, 'unsubscribe stops notifications');
});

test('createStore falls back to in-memory state when history/location are unavailable', () => {
  const store = createStore({ history: null, location: null });
  const state = store.update({ q: 'zürich', zoom: 14 });
  assert.equal(state.q, 'zürich');
  assert.equal(store.getState().zoom, 14);
});

test('the bus keeps one failing listener from taking down the others', () => {
  const bus = createBus();
  const calls = [];
  bus.on('ping', () => {
    throw new Error('boom');
  });
  bus.on('ping', (detail) => calls.push(detail));
  const originalError = console.error;
  console.error = () => {};
  try {
    bus.emit('ping', { ok: true });
  } finally {
    console.error = originalError;
  }
  assert.deepEqual(calls, [{ ok: true }]);
});

